import org.junit.jupiter.params.provider.ValueSource;

/**
 * Cardinality estimates of predicate-only patterns on a {@code spoc}-only store, where the predicate is a residual
 * field and the range covers more chunks than are counted exactly. Chunked statement records hold several statements
 * under the key of their first one, so sampling only chunk keys over-represents predicates that sort first within a
 * subject and under-represents the others (ExecPlan
 * {@code core/sail/lmdb/execplan-chunked-estimate-sampled-correction.md}).
 */
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class LmdbChunkedEstimateAccuracyTest {

	private static final int PEOPLE = 20_000;
	private static final int RANDOM_KNOWS_EDGES = 60_000;
	private static final double TOLERANCE = 0.10;

	@TempDir
	File dataDir;

	private SailRepository repository;

	@BeforeAll
	void buildStore() {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc").setForceSync(false)
				.setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(false)
				.setDirectAdjacencyMode(DirectAdjacencyMode.DISABLED);
		repository = new SailRepository(new LmdbStore(dataDir, config));
		repository.init();
		try (SailRepositoryConnection connection = repository.getConnection()) {
			new FoafCliqueDataGenerator(PEOPLE, 30, 3, 5, RANDOM_KNOWS_EDGES, 12345L).populate(connection);
		}
	}

	@AfterAll
	void shutDown() {
		if (repository != null) {
			repository.shutDown();
		}
	}

	@ParameterizedTest
	@ValueSource(strings = { "name", "knows" })
	void predicateOnlyEstimateIsCloseToExactCount(String localName) {
		IRI predicate = repository.getValueFactory().createIRI(FOAF.NAMESPACE, localName);
		String query = "SELECT * WHERE { ?s <" + predicate + "> ?o }";
		try (SailRepositoryConnection connection = repository.getConnection()) {
			long exact = exactCount(connection, predicate);
			GenericPlanNode plan = connection.prepareTupleQuery(query)
					.explain(Explanation.Level.Optimized)
					.toGenericPlanNode();
			List<GenericPlanNode> patterns = new ArrayList<>();
			collectStatementPatterns(plan, patterns);
			assertThat(patterns).as("statement patterns in %s", plan).hasSize(1);
			Double estimate = patterns.get(0).getResultSizeEstimate();
			assertThat(estimate).as("result size estimate in %s", plan).isNotNull();
			double ratio = estimate / exact;
			assertThat(ratio)
					.as("foaf:%s estimate %.0f vs exact %d (ratio %.2f)", localName, estimate, exact, ratio)
					.isBetween(1.0 - TOLERANCE, 1.0 + TOLERANCE);
		}
	}

	private static long exactCount(SailRepositoryConnection connection, IRI predicate) {
		try (var result = connection.prepareTupleQuery(
				"SELECT (COUNT(*) AS ?c) WHERE { ?s <" + predicate + "> ?o }").evaluate()) {
			return ((Literal) result.next().getValue("c")).longValue();
		}
	}

	private static void collectStatementPatterns(GenericPlanNode node, List<GenericPlanNode> out) {
		if (node.getType() != null && node.getType().startsWith("StatementPattern")) {
			out.add(node);
		}
		if (node.getPlans() != null) {
			for (GenericPlanNode child : node.getPlans()) {
				collectStatementPatterns(child, out);
			}
		}
	}
}
